`default_nettype none
`include "defines.sv"

// free input variables, can take any value each cycle as long as the `assume` are satisfied
module testbench (
	input check,
	input clock, reset
);
	`RVFI_WIRES
	`RVFI_BUS_WIRES

	`RISCV_FORMAL_CHECKER checker_inst (
		.clock  (clock),
		.reset  (reset),
		.check   (check),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

	// Ignore rvfi_order loopback, otherwise the check might be invalid.
	reg rvfi_order_loopback;
	always @(posedge clock) begin
		if (reset) begin
			rvfi_order_loopback <= 0;
		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
	// Shadow architectural GPR model built from RVFI.
	// Used to strengthen induction by eliminating unreachable CTIs where the
	// checker internal shadow state diverges from the architectural state.
	wire h_rvfi_valid = rvfi_valid[`RISCV_FORMAL_CHANNEL_IDX];
	wire h_rvfi_trap = rvfi_trap[`RISCV_FORMAL_CHANNEL_IDX];
	wire [4:0] h_rs1_addr = rvfi_rs1_addr[`RISCV_FORMAL_CHANNEL_IDX*5 +: 5];
	wire [4:0] h_rs2_addr = rvfi_rs2_addr[`RISCV_FORMAL_CHANNEL_IDX*5 +: 5];
	wire [4:0] h_rd_addr  = rvfi_rd_addr [`RISCV_FORMAL_CHANNEL_IDX*5 +: 5];
	wire [`RISCV_FORMAL_XLEN-1:0] h_rs1_rdata = rvfi_rs1_rdata[`RISCV_FORMAL_CHANNEL_IDX*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];
	wire [`RISCV_FORMAL_XLEN-1:0] h_rs2_rdata = rvfi_rs2_rdata[`RISCV_FORMAL_CHANNEL_IDX*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];
	wire [`RISCV_FORMAL_XLEN-1:0] h_rd_wdata  = rvfi_rd_wdata [`RISCV_FORMAL_CHANNEL_IDX*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];

	reg [`RISCV_FORMAL_XLEN-1:0] h_gpr_shadow [0:31];
	reg [31:0] h_gpr_written;
	integer h_i;

	always @(posedge clock) begin
		if (reset) begin
			for (h_i = 0; h_i < 32; h_i = h_i + 1) begin
				h_gpr_shadow[h_i] <= '0;
			end
			h_gpr_written <= 32'b0;
			h_gpr_shadow[0] <= '0;
			h_gpr_written[0] <= 1'b1;
		end else begin
			// x0 is hard-wired to zero.
			h_gpr_shadow[0] <= '0;
			h_gpr_written[0] <= 1'b1;

			// Check RS1/RS2 against the architectural shadow state.
			if (h_rvfi_valid) begin
				if (h_rs1_addr == 0) begin
					h_rs1_x0: assert(h_rs1_rdata == '0);
				end else if (h_gpr_written[h_rs1_addr]) begin
					h_rs1_shadow: assert(h_rs1_rdata == h_gpr_shadow[h_rs1_addr]);
				end

				if (h_rs2_addr == 0) begin
					h_rs2_x0: assert(h_rs2_rdata == '0);
				end else if (h_gpr_written[h_rs2_addr]) begin
					h_rs2_shadow: assert(h_rs2_rdata == h_gpr_shadow[h_rs2_addr]);
				end
			end

			// The checker instance's single-register shadow must agree with the
			// architectural shadow model whenever it claims to have observed a write.
			if (checker_inst.register_written) begin
				h_checker_written: assert(h_gpr_written[checker_inst.register_index]);
				h_checker_shadow: assert(checker_inst.register_shadow == h_gpr_shadow[checker_inst.register_index]);
			end

			// Update architectural shadow on successful retirement.
			if (h_rvfi_valid && !h_rvfi_trap) begin
				if (h_rd_addr != 0) begin
					h_gpr_shadow[h_rd_addr] <= h_rd_wdata;
					h_gpr_written[h_rd_addr] <= 1'b1;
				end
			end
		end
	end

/// Helper Assertion End
endmodule

