	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
	// Strengthen induction by relating RVFI register read data (and the checker
	// internal shadow) to the actual PicoRV32 register file.
	//
	// This blocks CTIs that exploit unconstrained internal state (e.g. checker
	// tracking a value that doesn't match the DUT architectural state).
	wire h_rvfi_valid = rvfi_valid[`RISCV_FORMAL_CHANNEL_IDX];
	wire [4:0] h_rs1_addr = rvfi_rs1_addr[`RISCV_FORMAL_CHANNEL_IDX*5 +: 5];
