	always @(posedge clock) begin
		if (!reset) begin
			if (h_rvfi_valid) begin
				if (h_rs1_addr == 0) begin
					h_rs1_x0: assert(h_rs1_rdata == '0);
				end else begin
					h_rs1_regfile: assert(h_rs1_rdata == wrapper.uut.cpuregs[h_rs1_addr]);
				end

				if (h_rs2_addr == 0) begin
					h_rs2_x0: assert(h_rs2_rdata == '0);
				end else begin
					h_rs2_regfile: assert(h_rs2_rdata == wrapper.uut.cpuregs[h_rs2_addr]);
				end
			end

			if (checker_inst.register_written) begin
				if (checker_inst.register_index == 0) begin
					h_checker_x0: assert(checker_inst.register_shadow == '0);
				end else begin
					h_checker_shadow: assert(checker_inst.register_shadow == wrapper.uut.cpuregs[checker_inst.register_index]);
				end
			end
		end
	end

/// Helper Assertion End
endmodule

