	wire [`RISCV_FORMAL_XLEN-1:0] h_rs2_rdata = rvfi_rs2_rdata[`RISCV_FORMAL_CHANNEL_IDX*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];
