	reg [`RISCV_FORMAL_XLEN-1:0] h_commit_gpr [0:31];
	reg [31:0] h_commit_valid;
	integer h_i;

	always @(posedge clock) begin
		if (reset) begin
			for (h_i = 0; h_i < 32; h_i = h_i + 1) begin
				h_commit_gpr[h_i] <= '0;
			end
			h_commit_valid <= 32'b0;
			h_commit_valid[0] <= 1'b1;
			h_commit_gpr[0] <= '0;
		end else begin
			// RVFI protocol/consistency helpers (proven facts about PicoRV32 RVFI).
			if ($past(!reset)) begin
				h_order_progress: assert(h_rvfi_order == $past(h_rvfi_order) + $past(h_rvfi_valid));
			end

			// Trap can only coincide with rvfi_valid on the *first* cycle of trap.
			// After trap is asserted, the core clears dbg_valid_insn, which forces
			// rvfi_valid low on subsequent trap cycles.
			if ($past(!reset)) begin
				h_trap_onecycle_valid: assert(!(h_rvfi_trap && $past(h_rvfi_trap) && h_rvfi_valid));
			end

			// x0 is always 0.
			h_commit_gpr[0] <= '0;
			h_commit_valid[0] <= 1'b1;

			// Update committed state on successful retirement.
			if (h_rvfi_valid && !h_rvfi_trap && h_rd_addr != 0) begin
				h_commit_gpr[h_rd_addr] <= h_rd_wdata;
				h_commit_valid[h_rd_addr] <= 1'b1;
			end

			// Only constrain reads on the instruction being checked by the original
			// checker (same gating: check && rvfi_valid && insn_order match).
			if (check && h_rvfi_valid && checker_inst.insn_order == h_rvfi_order) begin
				if (h_rs1_addr == 0) begin
					h_rs1_x0: assert(h_rs1_rdata == '0);
				end else if (h_commit_valid[h_rs1_addr]) begin
					h_rs1_shadow: assert(h_rs1_rdata == h_commit_gpr[h_rs1_addr]);
				end

				if (h_rs2_addr == 0) begin
					h_rs2_x0: assert(h_rs2_rdata == '0);
				end else if (h_commit_valid[h_rs2_addr]) begin
					h_rs2_shadow: assert(h_rs2_rdata == h_commit_gpr[h_rs2_addr]);
				end
			end

			// The checker internal shadow refers to a committed value for its chosen
			// register (it only becomes "written" after a retirement to that reg).
			if (checker_inst.register_written) begin
				h_checker_written: assert(h_commit_valid[checker_inst.register_index]);
				if (checker_inst.register_index == 0) begin
					h_checker_x0: assert(checker_inst.register_shadow == '0);
				end else begin
					h_checker_shadow: assert(checker_inst.register_shadow == h_commit_gpr[checker_inst.register_index]);
				end
			end
		end
	end

/// Helper Assertion End
endmodule

